const UA = { 'User-Agent': 'Pumpwise (pumpwiseapp@gmail.com; https://pumpwiseapp.com)', Accept: '*/*' };
const text = (h) => h.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/g, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');
const get = async (name, url) => { try { const r = await fetch(url, { headers: UA, redirect: 'follow', signal: AbortSignal.timeout(40000) }); const t = await r.text(); console.log(`== ${name} http=${r.status} url=${r.url} len=${t.length}`); return t; } catch (e) { console.log(`== ${name} FAILED ${e.message} ${e.cause?.code ?? ''}`); return ''; } };
const mails = (t) => [...new Set(t.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g) ?? [])].join(' ').replace(/@/g, ' AT ');
for (const lang of ['zh', 'en']) { const t = await get('mo station ' + lang, `https://consumer.dsedt.gov.mo/commodity/price_station.aspx?lang=${lang}`); const x = text(t); const i = x.search(/無鉛汽油零售價|Unleaded|Petrol/); console.log('   MO ' + x.slice(Math.max(0, i - 100), i + 1800)); console.log('   MO tables', (t.match(/<table/g) ?? []).length, 'rows', (t.match(/<tr/g) ?? []).length, 'links', [...new Set([...t.matchAll(/(?:href|src)="([^"]*(?:\.json|\.csv|\.xml|ashx|api|Handler)[^"]*)"/gi)].map((m) => m[1]))].join(' ')); const c = x.search(/版權|Copyright|copyright|使用條款|免責/); console.log('   MO terms ' + x.slice(Math.max(0, c - 100), c + 500)); if (lang === 'zh') console.log('   MO html ' + t.slice(t.search(/<table/), t.search(/<table/) + 1500).replace(/\s+/g, ' ')); }
for (const u of ['https://consumer.dsedt.gov.mo/Disclaimer.aspx?lang=en', 'https://consumer.dsedt.gov.mo/copyright.aspx?lang=en', 'https://consumer.dsedt.gov.mo/About/Disclaimer.aspx?lang=en']) { const t = text(await get('mo ' + u, u)); const c = t.search(/Disclaimer|Copyright|reproduc/i); console.log('   ' + t.slice(Math.max(0, c), c + 900)); }
for (const u of ['https://fmt.gov.ba/kontakt.html', 'https://fmt.gov.ba/novosti-2/informacije-o-kretanju-cijena.html', 'https://vladars.rs/sr-SP-Cyrl/Vlada/Ministarstva/MTT/Pages/default.aspx']) { const t = await get('ba ' + u, u); console.log('   mails', mails(t)); const x = text(t); const i = x.search(/oil info|aplikacij|апликациј/i); console.log('   ' + x.slice(Math.max(0, i - 200), i + 500)); console.log('   links', [...new Set([...t.matchAll(/href="([^"]*(?:play\.google|apps\.apple|oil|gorivo|goriv)[^"]*)"/gi)].map((m) => m[1]))].slice(0, 12).join(' ')); }
